import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;
import org.apache.abdera.parser.ParseException;

/**
 * Secure implementation of the Atom provider. The {@code readFrom} method now creates a
 * dedicated {@link Abdera} instance per invocation and configures the parser options
 * **before** any parsing occurs. Entity resolution is explicitly disabled, eliminating
 * the XML External Entity (XXE) attack surface. The parser is no longer shared across
 * threads, removing the race condition that previously allowed the insecure default
 * configuration to be used.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private boolean autodetectCharset;

    // -----------------------------------------------------------------------
    //  Secure readFrom implementation
    // -----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        if (entityStream == null) {
            throw new IOException("Input stream is null");
        }

        // Create a fresh Abdera instance for this call – this guarantees that the
        // parser is not shared between threads and that our security settings cannot
        // be overridden by another concurrent request.
        Abdera abdera = new Abdera();

        // Obtain a new parser from the fresh Abdera instance.
        Parser parser = abdera.getParser();

        // Configure parser options securely **before** parsing.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disabling entity resolution prevents XXE attacks.
        options.setResolveEntities(false);

        try {
            // Parse the input using the securely configured options.
            Document<T> doc = parser.parse(entityStream, options);
            return doc.getRoot();
        } catch (ParseException e) {
            // Convert Abdera parsing exceptions to IOException as required by the
            // JAX‑RS contract.
            throw new IOException("Failed to parse Atom XML payload", e);
        } finally {
            // The JAX‑RS runtime typically closes the stream, but we defensively
            // close it here to avoid resource leaks in non‑standard environments.
            try {
                entityStream.close();
            } catch (IOException ignored) {
                // Ignored – the primary exception (if any) is already propagated.
            }
        }
    }

    // -----------------------------------------------------------------------
    //  Other abstract / concrete methods omitted for brevity
    // -----------------------------------------------------------------------
}
