    /**
     * Allocates a file inside {@code dir} using the supplied {@code name}.
     * <p>
     * The method now validates {@code name} to prevent directory‑traversal attacks.
     * It removes any query string, strips path separators, rejects path‑traversal
     * components (e.g. "..") and finally verifies that the resulting file resides
     * within {@code dir} using canonical paths.
     *
     * @param dir  the target directory (must be non‑null and an existing directory)
     * @param name the original file name (may come from untrusted sources)
     * @return a {@link File} that does not yet exist inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid,
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Ensure the target directory exists (or can be created)
        if (!dir.isDirectory() && !dir.mkdirs()) {
            throw new IllegalArgumentException("Unable to create target directory: " + dir);
        }

        // 1. Remove any URL‑style query part (e.g. "file.txt?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // 2. Normalise the supplied name:
        //    - Replace Windows separators with Unix ones for uniform processing
        //    - Remove any path components, keeping only the final file name
        //    - Reject any traversal components like ".."
        name = name.replace('\\', '/');
        // Keep only the last segment after the final '/'
        int lastSlash = name.lastIndexOf('/');
        if (lastSlash >= 0) {
            name = name.substring(lastSlash + 1);
        }

        // After stripping path information, the name must not be empty
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name resolves to an empty string after sanitisation");
        }

        // Reject explicit traversal components that could have survived the above steps
        if (name.contains("..")) {
            throw new IllegalArgumentException("File name contains prohibited path traversal sequence '..'");
        }

        // 3. Build the initial File object
        File file = new File(dir, name);

        // 4. Verify that the canonical path of the file is still inside the canonical
        //    path of the target directory. This protects against any remaining edge‑cases.
        try {
            Path canonicalDir = dir.getCanonicalFile().toPath();
            Path canonicalFile = file.getCanonicalFile().toPath();
            if (!canonicalFile.startsWith(canonicalDir)) {
                throw new IllegalArgumentException(
                        "Resolved file path escapes the target directory: " + canonicalFile);
            }
        } catch (IOException e) {
            // Wrap checked exception as unchecked – callers cannot recover meaningfully.
            throw new IllegalArgumentException("Failed to resolve canonical paths", e);
        }

        // 5. If a file with the same name already exists, generate a unique one.
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // 6. Ensure the parent directory hierarchy exists.
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IllegalArgumentException("Unable to create directories for: " + parent);
        }

        return file;
    }

