import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;
import org.springframework.util.FileCopyUtils;

/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>Previous implementations allowed an external {@link Resource} to be used as a seed
 * via {@code SecureRandom#setSeed(byte[])}.  Supplying a predictable or attacker‑controlled
 * seed weakens the randomness and can lead to cryptographic compromise.  This revised
 * implementation never uses an externally supplied seed.  Instead it relies on the
 * built‑in, platform‑provided seeding mechanism which gathers entropy from the operating
 * system.</p>
 *
 * <p>If a custom algorithm is configured, the bean attempts to obtain an instance of that
 * algorithm.  If the algorithm is unavailable, it falls back to {@code SecureRandom.getInstanceStrong()}
 * which returns a strong, system‑default implementation.</p>
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    /** Default algorithm – kept for backward compatibility but not required. */
    private String algorithm = "SHA1PRNG";

    /** Optional seed resource – retained for API compatibility but ignored for security. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();

        // Trigger internal seeding without using any external data.
        // This call is inexpensive and guarantees the instance is fully initialized.
        rnd.nextBytes(new byte[1]);

        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // SecureRandom instances are not thread‑safe for reseeding,
        // therefore we expose a new instance each request.
        return false;
    }

    // -----------------------------------------------------------------------
    // Configuration setters (kept for compatibility)
    // -----------------------------------------------------------------------

    public void setAlgorithm(String algorithm) {
        this.algorithm = (algorithm != null && !algorithm.trim().isEmpty())
                ? algorithm.trim()
                : null;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }

    // -----------------------------------------------------------------------
    // Private helpers
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link SecureRandom} instance using the configured algorithm.
     * If the algorithm is unavailable or not set, {@link SecureRandom#getInstanceStrong()}
     * is used as a safe fallback.
     *
     * @return a securely seeded {@link SecureRandom}
     * @throws NoSuchAlgorithmException if no suitable algorithm can be found
     */
    private SecureRandom createSecureRandomInstance() throws NoSuchAlgorithmException {
        if (algorithm != null) {
            try {
                return SecureRandom.getInstance(algorithm);
            } catch (NoSuchAlgorithmException ex) {
                // Log the fallback (logging omitted for brevity) and continue to strong instance.
            }
        }
        // Strong instance is guaranteed to be a secure, system‑provided PRNG.
        return SecureRandom.getInstanceStrong();
    }
}
