        // ------------------------------------------------------------------
        final File targetFile = FileUtils.resolveFile(dir, entryName);

        // Resolve both paths to their canonical (real) forms.
        final Path canonicalDirPath  = dir.getCanonicalFile().toPath();
        final Path canonicalTargetPath = targetFile.getCanonicalFile().toPath();

        // Ensure the target stays inside the intended directory.
        if (!canonicalTargetPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException(
                "Entry is outside of the target directory (entryName=" + entryName + ")");
        }

        // ------------------------------------------------------------------
        // 2. If a symlink is to be created, validate its destination.
        // ------------------------------------------------------------------
        if (!StringUtils.isEmpty(symlinkDestination)) {
            final File symlinkTargetFile = new File(symlinkDestination);
            final Path canonicalSymlinkTargetPath = symlinkTargetFile.getCanonicalFile().toPath();

            // Disallow absolute symlink targets that point outside the extraction dir.
            if (!canonicalSymlinkTargetPath.startsWith(canonicalDirPath)) {
                throw new ArchiverException(
                    "Symlink destination is outside of the target directory (symlinkDestination="
                    + symlinkDestination + ")");
