protected static boolean isValid(String str) {
    if (str == null || str.isEmpty()) {
        return false;
    }
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        // reject any non-ASCII or control characters (including CR/LF)
        if (c < 0x21 || c > 0x7E) {
            return false;
        }
        if (c >= TOKEN_CHARS.length || !TOKEN_CHARS[c]) {
            return false;
        }
    }
    return true;
}
