    int index = 0;
    while (index < path.length() && path.charAt(index) == '/') {
        index++;
    }
    // The remainder of the path after removing leading slashes
    String remainder = path.substring(index);
    // Ensure there is exactly one leading slash
    return "/" + remainder;
}
