private static String normalizePath(final String path) {
    // Null input is considered a null path – keep the original contract.
    if (path == null) {
        return null;
    }

    /*
     * Remove **all** leading '/' characters.  The original implementation only
     * trimmed excess slashes but left the string unchanged when there was a
     * single leading slash, and it failed to add a slash when none were
     * present.  This could produce a path such as "example.com" which the URI
     * parser would treat as a host component, leading to URL‑spoofing issues.
     *
     * After stripping the leading slashes we explicitly prepend a single
     * '/' to guarantee a well‑formed absolute path component.
     */
    int firstNonSlash = 0;
    while (firstNonSlash < path.length() && path.charAt(firstNonSlash) == '/') {
        firstNonSlash++;
    }

    // The part of the path after the leading slashes (may be empty).
    String remainder = path.substring(firstNonSlash);

    // Always return a path that starts with exactly one '/'.
    return "/" + remainder;
}
