            int count = n & 0x7F;
            int value = readByte(in);
            if (value == -1) {
                throw new IOException("Unexpected end of stream while reading repeat value");
            }
            // ensure we don't write beyond buffer
            if (position + count > total) {
                throw new IOException("Decompressed data exceeds expected size");
            }
            for (int i = 0; i < count; i++) {
                out[position++] = (byte) value;
            }
        } else {
            int count = n;
            // ensure we don't read beyond buffer
            if (position + count > total) {
                throw new IOException("Decompressed data exceeds expected size");
