@Override
public ByteBuffer encode(final String name) {
    final CharsetEncoder enc = newEncoder();
    // Ensure encoder does not throw on errors; we will handle them manually
    enc.onMalformedInput(CodingErrorAction.REPORT);
    enc.onUnmappableCharacter(CodingErrorAction.REPORT);

    final CharBuffer cb = CharBuffer.wrap(name);
    ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

    // Process input characters
    while (cb.remaining() > 0) {
        CoderResult cr = enc.encode(cb, out, false);
        if (cr.isError()) {
            // Handle malformed or unmappable input
            int errLen = cr.length(); // number of characters that caused the error
            // Consume the problematic characters to guarantee progress
            for (int i = 0; i < errLen && cb.remaining() > 0; i++) {
                cb.get();
            }
            // Write the encoder's replacement bytes
            byte[] repl = enc.replacement();
            // Ensure there is enough space in the output buffer
            if (out.remaining() < repl.length) {
                out = ZipEncodingHelper.growBufferBy(out, repl.length - out.remaining());
            }
            out.put(repl);
            // Continue with next characters
            continue;
        }
        if (cr.isOverflow()) {
            // Grow the buffer enough for the remaining characters
            int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
            out = ZipEncodingHelper.growBufferBy(out, increment);
        }
        // If underflow, loop will exit when cb.remaining()==0
    }

    // Flush any remaining encoder state
    CoderResult flushResult = enc.encode(cb, out, true);
    while (flushResult.isOverflow()) {
        out = ZipEncodingHelper.growBufferBy(out, estimateIncrementalEncodingSize(enc, 1));
        flushResult = enc.encode(cb, out, true);
    }

    out.flip(); // set limit to current position and position to 0
    return out;
}
