import com.opensymphony.xwork2.util.LocalizedTextUtil;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Interceptor that handles i18n locale selection.
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Whitelist pattern for locale strings: language[_country[_variant]] */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2,3}(?:_[a-zA-Z]{2})?(?:_[a-zA-Z0-9]+)?$");

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link Locale} object from the request param, which might
     * already be a {@link Locale} or a {@link String}. The input is validated
     * against a strict whitelist to prevent malicious values (e.g., XSS payloads).
     *
     * @param requestedLocale the parameter from the request
     * @return a {@link Locale} instance or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // If the caller already supplied a Locale, trust it.
        if (requestedLocale instanceof Locale) {
            return (Locale) requestedLocale;
        }

        // Convert to String and trim whitespace.
        String localeStr = requestedLocale.toString().trim();

        // Validate against the whitelist pattern.
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Rejected invalid locale parameter: [{}]", localeStr);
            return null;
        }

        // Parse the locale safely; any unexpected exception results in a null.
        try {
            Locale locale = LocalizedTextUtil.localeFromString(localeStr, null);
            if (locale != null) {
                LOG.debug("Applied request locale: {}", locale);
            }
            return locale;
        } catch (Exception e) {
            LOG.warn("Failed to parse locale parameter: [{}]", localeStr, e);
            return null;
        }
    }

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------
}
