/**
 * DefaultActionMapper – patched version.
 *
 * The {@code cleanupActionName} method has been hardened.
 * Instead of trying to “clean” an invalid name by stripping out
 * matching chunks (which could leave malicious characters untouched),
 * the method now either:
 *   1) Returns the original name when it fully complies with the whitelist
 *      pattern, or
 *   2) Removes **all** characters that are not explicitly allowed.
 *
 * This whitelist‑only approach guarantees that no disallowed characters
 * survive the sanitisation step, eliminating the previous bypass.
 */
public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);

    /** Whitelist of characters that are permitted in an action name. */
    protected final Pattern allowedActionNames = Pattern.compile("[a-zA-Z0-9._!/\\-]*");

    /** Pattern that matches any character *not* in the whitelist. */
    private static final Pattern disallowedChars = Pattern.compile("[^a-zA-Z0-9._!/\\-]");

    // -----------------------------------------------------------------
    // other methods (omitted for brevity)
    // -----------------------------------------------------------------

    /**
     * Cleans up action name from suspicious characters.
     *
     * <p>If the supplied {@code rawActionName} fully matches the whitelist
     * pattern, it is returned unchanged.  Otherwise, every character that
     * does not belong to the whitelist is stripped out.  This guarantees
     * that the resulting string contains only safe characters.</p>
     *
     * @param rawActionName action name extracted from URI; may be {@code null}
     * @return a safe action name (never {@code null})
     */
    protected String cleanupActionName(final String rawActionName) {
        // Defensive programming – treat {@code null} as an empty string.
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null action name; treating as empty.");
            }
            return "";
        }

        // Fast path: the whole name is already safe.
        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        }

        // Log the anomaly before sanitising.
        if (LOG.isWarnEnabled()) {
            LOG.warn("Action/method [{}] does not match allowed action names pattern [{}]; sanitising it.",
                    rawActionName, allowedActionNames.pattern());
        }

        // Remove every character that is not explicitly allowed.
        String cleanActionName = disallowedChars.matcher(rawActionName).replaceAll("");

        if (LOG.isDebugEnabled()) {
            LOG.debug("Sanitised action/method name [{}] -> [{}]", rawActionName, cleanActionName);
        }

        return cleanActionName;
    }

    // -----------------------------------------------------------------
    // other methods (omitted for brevity)
