private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path targetPath = targetDirectory.toPath().toRealPath().normalize();
    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String entryName = entry.getName();
        if (entryName == null) {
            throw new IOException("Archive entry name is null");
        }
        // Reject absolute paths
        if (new File(entryName).isAbsolute()) {
            throw new IOException("Entry name '" + entryName + "' is absolute");
        }
        // Resolve the entry against the target directory and normalize
        Path resolvedPath = targetPath.resolve(entryName).normalize();

        // Ensure the resolved path is still within the target directory
        if (!resolvedPath.startsWith(targetPath)) {
            throw new IOException("Entry '" + entryName + "' would be extracted outside of target directory");
        }

        File f = resolvedPath.toFile();

        if (entry.isDirectory()) {
            // create directory if not exists
            if (!f.isDirectory() && !f.mkdirs()) {
                throw new IOException("Failed to create directory " + f);
            }
        } else {
            // ensure parent directory exists
            File parent = f.getParentFile();
            if (parent != null && !parent.isDirectory() && !parent.mkdirs()) {
                throw new IOException("Failed to create directory " + parent);
            }
            // write file content
            try (OutputStream out = Files.newOutputStream(resolvedPath, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(entry, out);
            }
        }

        entry = supplier.getNextReadableEntry();
    }
}
