protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
    if (body == null) {
        return null;
    }
    Class<?> type = getDocumentType();
    // If requested type is Document, try to convert directly
    if (type != null && Document.class.isAssignableFrom(type)) {
        // try type conversion first
        try {
            Object answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            if (answer != null) {
                return answer;
            }
        } catch (Exception ignored) {
            // fallback to secure parsing
        }
    }

    InputSource inputSource = null;
    if (body instanceof WrappedFile) {
        InputStream is = exchange.getContext().getTypeConverter().convertTo(InputStream.class, exchange, body);
        if (is != null) {
            inputSource = new InputSource(is);
        }
    } else if (body instanceof BeanInvocation) {
        BeanInvocation bi = exchange.getContext().getTypeConverter().convertTo(BeanInvocation.class, exchange, body);
        if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
            return null;
        }
    } else if (body instanceof String) {
        inputSource = new InputSource(new StringReader((String) body));
    } else {
        // fallback: try to get InputStream
        InputStream is = exchange.getContext().getTypeConverter().convertTo(InputStream.class, exchange, body);
        if (is != null) {
            inputSource = new InputSource(is);
        }
    }

    if (inputSource == null) {
        // No suitable conversion, return original body if type not required
        if (type == null) {
            return body;
        }
        throw new NoTypeConversionAvailableException(body, type);
    }

    // Securely parse InputSource into Document
    DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
    dbf.setNamespaceAware(true);
    // Secure processing features
    try {
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
    } catch (ParserConfigurationException ignored) {}
    try {
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
    } catch (ParserConfigurationException ignored) {}
    try {
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
    } catch (ParserConfigurationException ignored) {}
    try {
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
    } catch (ParserConfigurationException ignored) {}
    dbf.setXIncludeAware(false);
    dbf.setExpandEntityReferences(false);

    DocumentBuilder db = dbf.newDocumentBuilder();
    Document doc = db.parse(inputSource);
    return doc;
}
