import com.alibaba.fastjson.parser.deserializer.ObjectDeserializer;
import com.alibaba.fastjson.util.TypeUtils;

/**
 * Secure implementation of an ObjectArray deserializer.
 *
 * <p>
 * The original implementation relied on Fastjson's default configuration,
 * which (in versions prior to 1.2.25) allowed automatic type resolution via the
 * {@code @type} field.  An attacker could therefore supply a crafted JSON payload
 * that caused arbitrary classes to be instantiated – a classic deserialization
 * RCE vector.
 * </p>
 *
 * <p>
 * This patched version mitigates the issue by:
 * <ul>
 *   <li>Explicitly disabling Fastjson's auto‑type support and enabling safe‑mode
 *       for the parser used in this call.</li>
 *   <li>Whitelisting the component type of the array – only primitive wrappers,
 *       {@link String}, {@link Number} subclasses and a few well‑known immutable
 *       types are allowed.  Any other type results in a {@link JSONException}.</li>
 *   <li>Preserving the original behaviour for {@code null} and string literals
 *       (which are converted to {@code byte[]} as before).</li>
 * </ul>
 * </p>
 *
 * The method is now safe for production use with Fastjson versions that may still
 * contain the vulnerable auto‑type feature.
 */
public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    // -----------------------------------------------------------------------
    //  Deserialization
    // -----------------------------------------------------------------------
    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        /* --------------------------------------------------------------------
         * 1. Harden the parser configuration – disable auto type and enable safe
         *    mode.  This prevents Fastjson from honouring any {@code @type}
         *    attribute that may be present in the JSON payload.
         * -------------------------------------------------------------------- */
        ParserConfig config = parser.getConfig();
        config.setAutoTypeSupport(false);   // turn off the vulnerable feature
        config.setSafeMode(true);           // extra safety checks inside Fastjson

        /* --------------------------------------------------------------------
         * 2. Normal fastjson token handling (null / string literal) – unchanged.
         * -------------------------------------------------------------------- */
        final JSONLexer lexer = parser.lexer;

        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        /* --------------------------------------------------------------------
         * 3. Resolve the component class of the target array.
         * -------------------------------------------------------------------- */
        Class componentClass;
        Type componentType;

        if (type instanceof GenericArrayType) {
            GenericArrayType gat = (GenericArrayType) type;
            componentType = gat.getGenericComponentType();

            if (componentType instanceof TypeVariable) {
                // Resolve a type variable against the parser context (generic method/field)
                TypeVariable<?> tv = (TypeVariable<?>) componentType;
                Type ctxType = parser.getContext().type;

                if (ctxType instanceof ParameterizedType) {
                    ParameterizedType pt = (ParameterizedType) ctxType;
                    Type raw = pt.getRawType();

                    if (raw instanceof Class) {
                        Type actual = resolveTypeVariable((Class<?>) raw, pt, tv);
                        componentClass = (actual instanceof Class) ? (Class) actual : Object.class;
                    } else {
                        componentClass = Object.class;
                    }
                } else {
                    // Fallback – use the first bound of the type variable
                    componentClass = TypeUtils.getClass(tv.getBounds()[0]);
                }
            } else {
                componentClass = TypeUtils.getClass(componentType);
            }
        } else {
            // Plain array class, e.g. String[]
            Class<?> arrayClass = (Class<?>) type;
            componentClass = arrayClass.getComponentType();
            componentType = componentClass;
        }

        /* --------------------------------------------------------------------
         * 4. Whitelist validation – only allow safe component types.
         * -------------------------------------------------------------------- */
        if (!isSafeComponentClass(componentClass)) {
            throw new JSONException(
                    "Deserialization of array component type '" + componentClass.getName()
                            + "' is not permitted for security reasons");
        }

        /* --------------------------------------------------------------------
         * 5. Parse the JSON array into a JSONArray using the (now safe) parser.
         * -------------------------------------------------------------------- */
