    // -----------------------------------------------------------------------
    //  Helper methods
    // -----------------------------------------------------------------------

    /**
     * Resolve a {@link TypeVariable} against a concrete {@link ParameterizedType}
     * and its raw class.
     */
    private static Type resolveTypeVariable(Class<?> rawClass,
                                            ParameterizedType paramType,
                                            TypeVariable<?> typeVar) {
        TypeVariable<?>[] typeParams = rawClass.getTypeParameters();
        for (int i = 0; i < typeParams.length; i++) {
            if (typeParams[i].getName().equals(typeVar.getName())) {
                return paramType.getActualTypeArguments()[i];
            }
        }
        return null;
    }

    /**
     * Determines whether the supplied component class is considered safe for
     * deserialization.  The whitelist deliberately contains only immutable or
     * primitive‑wrapper types that cannot trigger arbitrary code execution.
