    /**
     * Creates a {@link SAXSource} from a {@link StreamSource} while protecting against
     * XXE attacks. The method configures the underlying parser to disallow DTDs,
     * external general entities, and external parameter entities.
     *
     * @param source   the incoming XML as a {@link StreamSource}
     * @param exchange the Camel exchange (may be {@code null})
     * @return a securely configured {@link SAXSource}
     * @throws SAXException if a safe {@link XMLReader} cannot be instantiated
     */
    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        if (source == null) {
            throw new SAXException("StreamSource must not be null");
        }

        // -----------------------------------------------------------------
        // Build the InputSource from the StreamSource (reader takes precedence)
        // -----------------------------------------------------------------
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else if (source.getInputStream() != null) {
            inputSource = new InputSource(source.getInputStream());
        } else {
            throw new SAXException("StreamSource does not contain a Reader or InputStream");
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        // ---------------------------------------------------------------
        // Obtain (or create) a SAXParserFactory and harden it against XXE
        // ---------------------------------------------------------------
        SAXParserFactory sfactory = null;
        if (exchange != null) {
            sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
        }
        if (sfactory == null) {
            sfactory = SAXParserFactory.newInstance();
        }

        // The following features are required for a secure configuration.
        // Each call is wrapped individually so that a missing feature does not
        // prevent the rest of the hardening from being applied.
        try {
            sfactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        } catch (Exception e) {
            LOG.warn("Unable to set FEATURE_SECURE_PROCESSING on SAXParserFactory: {}", e.toString());
        }
        try {
            sfactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        } catch (Exception e) {
            LOG.warn("Unable to disable external-general-entities: {}", e.toString());
        }
        try {
            sfactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        } catch (Exception e) {
            LOG.warn("Unable to disable external-parameter-entities: {}", e.toString());
        }

        // Ensure the parser does not attempt validation (which would trigger DTD loading)
        sfactory.setNamespaceAware(true);
        sfactory.setValidating(false);

        // ---------------------------------------------------------------
        // Create the XMLReader and apply reader‑specific hardening features
        // ---------------------------------------------------------------
        XMLReader xmlReader;
        try {
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Disallow DOCTYPE declarations entirely – this is the most effective
            // mitigation against XXE.
            try {
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.warn("Unable to disallow DOCTYPE declarations: {}", e.toString());
            }

            // Prevent loading of any external DTDs or DTD grammars.
            try {
                xmlReader.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            } catch (Exception e) {
                LOG.warn("Unable to disable loading of external DTDs: {}", e.toString());
            }
            try {
                xmlReader.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            } catch (Exception e) {
                LOG.warn("Unable to disable loading of DTD grammar: {}", e.toString());
            }

