            // If we cannot obtain a safe XMLReader we fail fast – returning a partially
            // configured reader would re‑introduce the XXE risk.
            LOG.warn("Cannot create a secure SAXParser XMLReader, due to {}", ex.toString());
            throw new SAXException("Failed to create a secure XMLReader", ex);
        }

        // -----------------------------------------------------------------
        // Return the securely configured SAXSource
        // -----------------------------------------------------------------
        return new SAXSource(xmlReader, inputSource);
    }

    // -------------------------------------------------------------------------
    // Additional conversion utilities (omitted for brevity)
    // -------------------------------------------------------------------------
