import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // other methods ...

    /**
     * Determines whether the caller is allowed to update the user identified by the path variable.
     * <p>
     * The method now enforces strict authorization:
     * <ul>
     *   <li>The request must be authenticated (a {@link Principal} must be present).</li>
     *   <li>The authenticated user ID must match the ID extracted from the request URL,
     *       unless the caller has an administrative role.</li>
     *   <li>All mutable fields are compared against the persisted user to ensure that
     *       no unauthorized changes are performed.</li>
     * </ul>
     *
     * @param request the incoming HTTP request
     * @return {@code true} if the update is allowed, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // ---- 1. Authenticate the caller ---------------------------------------------------------
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated user – deny the operation
            return false;
        }
        String authenticatedUserId = principal.getName();
        if (authenticatedUserId == null || authenticatedUserId.isEmpty()) {
            return false;
        }

        // ---- 2. Extract the target user ID from the request URL ---------------------------------
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );

        // ---- 3. Authorisation check -------------------------------------------------------------
        // Allow the operation only if the caller is updating their own account
        // or if they possess an administrative role.
        boolean isAdmin = request.isUserInRole("admin") || request.isUserInRole("uaa.admin");
        if (!isAdmin && !Objects.equals(authenticatedUserId, id)) {
            // The caller tries to modify another user's account without admin rights.
            return false;
        }

        // ---- 4. Parse the incoming payload -------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // ---- 5. Load the persisted user -----------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot safely allow an update.
            return false;
        }

        // ---- 6. Validate immutable fields ---------------------------------------------------------
        // The following fields must not be altered by a self‑update request.
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed.
        return true;
    }

    // other methods ...

}
